// TestStreamsJoint — packaged-playback box 4.2, the lane ↔ stream ↔ scan
// joint. The unit suite (enrich/streams_test.go) drives the lane over a FAKE
// PackItem; this test drives it over the REAL stream.Service.Pack (real
// ffmpeg) and the REAL scan-persisted documents, so only a cross-module
// failure can catch it:
//
//   - pack_failed: a real ffmpeg failure on a corrupt fixture records the
//     pack_failed ledger row under __streams__ with the FLAT 30-day cooldown —
//     an immediate retry advances attempts but never doubles the cooldown —
//     and the item's lifecycle status is untouched (no metadata semantics).
//   - lease renew: an injected long run (the task-sanctioned gate wrapped
//     AROUND the real pack) survives several lease TTLs because the lane
//     renews; a concurrent dispatch is dropped while alive and the item is
//     re-dispatchable after, under a fresh build nonce.
//   - rescan carry-forward: an unchanged-base re-scan carries the packaged
//     state verbatim (same artifact pointer, still playable end-to-end); a
//     changed-base re-scan drops it (mode direct, state none).
package itest

import (
	"context"
	"encoding/json"
	"net/http"
	"path/filepath"
	"strings"
	"sync"
	"sync/atomic"
	"testing"
	"time"

	"github.com/mellifera/mellifera/internal/enrich"
	"github.com/mellifera/mellifera/internal/store"
)

func TestStreamsJoint(t *testing.T) {
	w := pbNewWorld(t)
	q := w.pbNewQueue(t, nil, 0) // the world queue: real pack, production lease TTL
	enqueue := w.pbEnqueue(q)

	t.Run("pack_failed_flat_cooldown", func(t *testing.T) {
		libRoot := t.TempDir()
		pbWriteGarbage(t, filepath.Join(libRoot, "Broken File.mkv"))
		libID := pbCreateLibrary(t, w, "tv", libRoot, "QA Streams Corrupt")
		pbScanLibrary(t, w, libID)
		pbAwaitIdle(t, q, 30*time.Second)
		itemID := pbItemByRel(t, w, libID)["Broken File.mkv"].ID
		if itemID == "" {
			t.Fatalf("corrupt fixture not persisted")
		}
		before, err := w.st.GetItem(context.Background(), itemID)
		if err != nil {
			t.Fatalf("GetItem before pack: %v", err)
		}

		// First real pack: ffmpeg fails on the garbage bytes → terminal
		// pack_failed with the flat 30-day cooldown.
		if err := enqueue(itemID); err != nil {
			t.Fatalf("EnqueuePack: %v", err)
		}
		failed := pbAwaitStreams(t, w.st, itemID, "failed", 60*time.Second)
		if failed["reason"] == "" || failed["failed_at"] == "" {
			t.Fatalf("failed streams doc missing reason/failed_at: %v", failed)
		}
		row1 := pbLedgerRow(t, w.st, itemID)
		if row1.Status != "pack_failed" {
			t.Fatalf("ledger status = %q, want pack_failed", row1.Status)
		}
		cool1 := row1.NextEligibleAt.Sub(row1.FailedAt)
		if cool1 < 29*24*time.Hour || cool1 > 31*24*time.Hour {
			t.Fatalf("first cooldown = %v, want ~30d flat", cool1)
		}
		// Metadata completion is untouched: lifecycle status exactly as scan
		// left it, and the only document change is the streams namespace.
		after, err := w.st.GetItem(context.Background(), itemID)
		if err != nil {
			t.Fatalf("GetItem after pack: %v", err)
		}
		if after.Status != before.Status {
			t.Fatalf("item status moved %q -> %q on a pack failure (lane must not touch lifecycle)", before.Status, after.Status)
		}

		// Immediate retry: attempts advance, the cooldown stays FLAT (no
		// doubling — the retry path would otherwise punish explicit retries).
		if err := enqueue(itemID); err != nil {
			t.Fatalf("retry EnqueuePack: %v", err)
		}
		deadline := time.Now().Add(60 * time.Second)
		var row2 store.FailureRow
		for {
			row2 = pbLedgerRow(t, w.st, itemID)
			if row2.Attempts == row1.Attempts+1 {
				break
			}
			if time.Now().After(deadline) {
				t.Fatalf("retry never recorded: attempts %d, want %d", row2.Attempts, row1.Attempts+1)
			}
			time.Sleep(5 * time.Millisecond)
		}
		cool2 := row2.NextEligibleAt.Sub(row2.FailedAt)
		if cool2 < 29*24*time.Hour || cool2 > 31*24*time.Hour {
			t.Fatalf("retry cooldown = %v, want ~30d flat (no doubling)", cool2)
		}
		if spread := row2.NextEligibleAt.Sub(row1.FailedAt); spread > 35*24*time.Hour {
			t.Fatalf("retry pushed eligibility %v past the first failure — the cooldown doubled", spread)
		}
	})

	t.Run("long_run_renews_lease", func(t *testing.T) {
		libRoot := t.TempDir()
		pbMakeMKV(t, filepath.Join(libRoot, "Lease File.mkv"), 5*time.Second, false)
		libID := pbCreateLibrary(t, w, "tv", libRoot, "QA Streams Lease")
		pbScanLibrary(t, w, libID)
		pbAwaitIdle(t, q, 30*time.Second)
		itemID := pbItemByRel(t, w, libID)["Lease File.mkv"].ID
		if itemID == "" {
			t.Fatalf("lease fixture not persisted")
		}

		// The injected long run: a gate wrapped AROUND the real pack (the pack
		// itself still runs). TTL 50ms with the gate held ~150ms means the run
		// outlives 3 TTLs — only the lane's renewal keeps it alive.
		const leaseTTL = 50 * time.Millisecond
		gate := make(chan struct{})
		var gateOnce sync.Once
		release := func() { gateOnce.Do(func() { close(gate) }) }
		t.Cleanup(release) // never let a cleanup hang on a still-blocked worker
		var calls atomic.Int32
		entered := make(chan struct{}, 8)
		pack := func(ctx context.Context, itemID, absPath string, ffprobe map[string]any) (enrich.PackOutcome, error) {
			calls.Add(1)
			entered <- struct{}{}
			select {
			case <-gate:
			case <-ctx.Done():
				return enrich.PackOutcome{}, ctx.Err()
			}
			build, err := w.media.Pack(ctx, itemID, absPath, ffprobe)
			return enrich.PackOutcome{Playlist: build.Playlist, Nonce: build.Nonce}, err
		}
		qq := w.pbNewQueue(t, pack, leaseTTL)

		if err := qq.EnqueuePack(itemID); err != nil {
			t.Fatalf("EnqueuePack: %v", err)
		}
		select {
		case <-entered:
		case <-time.After(30 * time.Second):
			t.Fatalf("the long run never entered PackItem")
		}
		time.Sleep(3 * leaseTTL) // the run now outlives 3 TTLs

		// A concurrent dispatch while the run is alive: blocked by the lease
		// (kept alive by renewal — a broken renewal would have expired the
		// lease at 1 TTL, and this dispatch would run concurrently).
		if err := qq.EnqueuePack(itemID); err != nil {
			t.Fatalf("concurrent EnqueuePack: %v", err)
		}
		deadline := time.Now().Add(10 * leaseTTL)
		for time.Now().Before(deadline) {
			if calls.Load() > 1 {
				t.Fatalf("PackItem ran concurrently while the long run was alive past %v — the lease renewal is broken", 3*leaseTTL)
			}
			time.Sleep(2 * time.Millisecond)
		}
		if got := calls.Load(); got != 1 {
			t.Fatalf("PackItem calls = %d during the alive run, want 1", got)
		}

		// Release: the run completes through the REAL pack and persists.
		release()
		streams := pbAwaitStreams(t, w.st, itemID, "complete", 60*time.Second)
		if got := calls.Load(); got != 1 {
			t.Fatalf("PackItem calls after release = %d, want 1 (the blocked dispatch must have been dropped)", got)
		}
		nonce1, _ := streams["nonce"].(string)
		if nonce1 == "" {
			t.Fatalf("completed run missing nonce: %v", streams)
		}

		// Re-dispatchable after: a fresh run publishes under a FRESH nonce.
		// Poll the DOC's nonce, not the state — the doc never left "complete"
		// between runs, so a state-based await would return run 1's stale doc.
		if err := qq.EnqueuePack(itemID); err != nil {
			t.Fatalf("re-dispatch EnqueuePack: %v", err)
		}
		deadline = time.Now().Add(60 * time.Second)
		var nonce2 string
		for {
			it, err := w.st.GetItem(context.Background(), itemID)
			if err != nil {
				t.Fatalf("GetItem after re-dispatch: %v", err)
			}
			var doc map[string]any
			if err := json.Unmarshal(it.Document, &doc); err != nil {
				t.Fatalf("decode doc after re-dispatch: %v", err)
			}
			s, _ := doc["streams"].(map[string]any)
			if s != nil {
				nonce2, _ = s["nonce"].(string)
			}
			if nonce2 != "" && nonce2 != nonce1 {
				break
			}
			if time.Now().After(deadline) {
				t.Fatalf("item was not re-dispatchable after the run ended (doc nonce %q, first nonce %q)", nonce2, nonce1)
			}
			time.Sleep(5 * time.Millisecond)
		}
	})

	t.Run("rescan_carry_forward", func(t *testing.T) {
		libRoot := t.TempDir()
		fixture := filepath.Join(libRoot, "Carry File.mkv")
		pbMakeMKV(t, fixture, 5*time.Second, false)
		libID := pbCreateLibrary(t, w, "tv", libRoot, "QA Streams Carry")
		pbScanLibrary(t, w, libID)
		pbAwaitIdle(t, q, 30*time.Second)
		itemID := pbItemByRel(t, w, libID)["Carry File.mkv"].ID
		if itemID == "" {
			t.Fatalf("carry fixture not persisted")
		}

		if err := enqueue(itemID); err != nil {
			t.Fatalf("EnqueuePack: %v", err)
		}
		pbAwaitStreams(t, w.st, itemID, "complete", 60*time.Second)
		pbAwaitIdle(t, q, 30*time.Second)
		desc := pbDescriptor(t, w, itemID)
		if desc.Mode != "hls" || desc.State != "complete" {
			t.Fatalf("descriptor after pack = mode %q state %q, want hls/complete", desc.Mode, desc.State)
		}
		assertPlayable(t, w, desc.PlayURL)

		// Unchanged-base re-scan: the packaged state is carried forward
		// verbatim (same artifact pointer) and stays playable end-to-end.
		pbScanLibrary(t, w, libID)
		pbAwaitIdle(t, q, 30*time.Second)
		carried := pbDescriptor(t, w, itemID)
		if carried.Mode != "hls" || carried.State != "complete" {
			t.Fatalf("descriptor after unchanged rescan = mode %q state %q, want hls/complete (carry-forward)", carried.Mode, carried.State)
		}
		// Compare the artifact POINTER (path sans query), not the full URL:
		// the play URL embeds a freshly minted token whose payload carries
		// expires.Unix() at second resolution (stream/describe.go, token.go) —
		// two mints straddling a second boundary differ in the query only,
		// which is token noise, not a carry break. Same nonce/build pointer
		// is the verbatim-carry property.
		if got := stripToken(carried.PlayURL); got != stripToken(desc.PlayURL) {
			t.Fatalf("artifact pointer changed %q -> %q on an unchanged rescan (carry must be verbatim)", stripToken(desc.PlayURL), got)
		}
		assertPlayable(t, w, carried.PlayURL)

		// Changed-base re-scan (regenerated media: different duration): the
		// stale packaging state is dropped — mode direct, streams key gone.
		pbMakeMKV(t, fixture, 3*time.Second, false)
		pbScanLibrary(t, w, libID)
		pbAwaitIdle(t, q, 30*time.Second)
		dropped := pbDescriptor(t, w, itemID)
		if dropped.Mode != "direct" || dropped.State != "none" {
			t.Fatalf("descriptor after changed rescan = mode %q state %q, want direct/none (changed base drops streams)", dropped.Mode, dropped.State)
		}
		it, err := w.st.GetItem(context.Background(), itemID)
		if err != nil {
			t.Fatalf("GetItem after changed rescan: %v", err)
		}
		var doc map[string]any
		if err := json.Unmarshal(it.Document, &doc); err != nil {
			t.Fatalf("decode doc: %v", err)
		}
		if _, still := doc["streams"]; still {
			t.Fatalf("changed-base rescan kept doc[streams]: %v", doc["streams"])
		}
	})
}

// assertPlayable fetches a playlist URL (token carried in its query) and
// asserts a complete, byte-servable build.
func assertPlayable(t *testing.T, w *pbWorld, playURL string) {
	t.Helper()
	status, body, _ := pbDo(t, w.client, http.MethodGet, w.baseURL+playURL, "", nil)
	if status != http.StatusOK {
		t.Fatalf("playlist %s: status %d, want 200", playURL, status)
	}
	if !strings.Contains(string(body), "#EXTM3U") || !strings.Contains(string(body), "#EXT-X-ENDLIST") {
		t.Fatalf("playlist %s missing a complete build marker:\n%s", playURL, body)
	}
}

// pbLedgerRow fetches the item's __streams__ ledger row (fails when absent).
func pbLedgerRow(t *testing.T, st *store.Store, itemID string) store.FailureRow {
	t.Helper()
	rows, err := st.ListFailures(context.Background())
	if err != nil {
		t.Fatalf("ListFailures: %v", err)
	}
	for _, r := range rows {
		if r.ItemID == itemID && r.PluginID == pbStreamsLane {
			return r
		}
	}
	t.Fatalf("no __streams__ ledger row for %s; rows=%+v", itemID, rows)
	return store.FailureRow{}
}
